select c.id,c.member_id,c.name,c.logo,c.member_count,c.status,c.del_flag, exists(select 1 from club_member cm where cm.club_id=c.id and cm.member_id=#{memberId} and cm.status=1 and cm.del_flag=0) as viewer_member from club c where c.del_flag=0
and c.id in #{clubId}
and 1=0

select id, conversation_id, member_id, role, unread_count, last_read_msg_id, muted, deleted, create_time
from im_conversation_member
where conversation_id = #{conversationId}
